from typing import List, Dict
class LongTermMemory:
    def __init__(self, embedding_model):
        self.embedding_model = embedding_model
        self.vectors = []          # 存储向量
        self.texts = []             # 存储原始文本
        self.metadatas = []         # 存储元数据（如时间戳、重要性等）
    def _embed(self, text: str) -&gt; np.ndarray:
        return self.embedding_model.encode(text)
    def add(self, text: str, metadata: dict = None):
        &#34;&#34;&#34;将一段文本存入长期记忆。&#34;&#34;&#34;
        vector = self._embed(text)
        self.vectors.append(vector)
        self.texts.append(text)
        self.metadatas.append(metadata or {})
    def query(self, query_text: str, top_k: int = 3) -&gt; List[str]:
        &#34;&#34;&#34;根据查询文本，返回最相关的 top_k 条记忆文本。&#34;&#34;&#34;
        if not self.vectors:
            return []
        query_vec = self._embed(query_text)
        # 计算余弦相似度
        similarities = [
            np.dot(query_vec, v) / (np.linalg.norm(query_vec) * np.linalg.norm(v))
            for v in self.vectors
        ]
        top_indices = np.argsort(similarities)[-top_k:][::-1]
        return [self.texts[i] for i in top_indices]记忆管理器（整合短期与长期） 记忆管理器专门负责管理记忆存储，还提供构建最终提示词的方法。核心逻辑是： 1. 从短期记忆里拿到最近的对话历史 2. 从长期记忆里检索和当前问题相关的背景知识 3. 把长期记忆当成系统提示的一部分，短期记忆按顺序排列，最后加上当前用户输入，组成完整的 messages 列表 class MemoryManager:
    def __init__(self, embedding_model, short_term_max_messages=20, long_term_top_k=3):
        self.short_term = ShortTermMemory(max_messages=short_term_max_messages)
